 "content": "from collections import Counter, deque


def transform(grid):
    """Keep large solid-color rectangular objects; erase scattered noise."""
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    out = [[background for _ in range(w)] for _ in range(h)]
    visited = set()

    for color, count in counts.items():
        if color == background or count < 8:
            continue
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in visited:
                    continue
                q = deque([(r, c)])
                visited.add((r, c))
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if (0 <= ny < h and 0 <= nx < w
                                    and grid[ny][nx] == color
                                    and (ny, nx) not in visited):
                                visited.add((ny, nx))
                                q.append((ny, nx))
                if len(cells) < 8:
                    continue
                r0 = min(y for y, _ in cells)
                r1 = max(y for y, _ in cells)
                c0 = min(x for _, x in cells)
                c1 = max(x for _, x in cells)
                for y in range(r0, r1 + 1):
                    for x in range(c0, c1 + 1):
                        out[y][x] = color
    return out


